const transactions = $input.all();

let totalPenjualan = 0;
let totalDiskon = 0;
let totalPPN = 0;
let totalTunai = 0;
let totalDebit = 0;
let totalQRIS = 0;
let totalTransaksi = 0;
const produkTerlaris = {};

for (const tx of transactions) {
  const data = tx.json;
  const items = data.items || [data];
  for (const item of items) {
    totalPenjualan += Number(item.subtotal || item.amount || 0);
    totalDiskon += Number(item.discount || 0);
    totalPPN += Number(item.ppn || item.tax || 0);

    const produk = item.product_name || item.nama_produk || 'Unknown';
    produkTerlaris[produk] = (produkTerlaris[produk] || 0) + Number(item.qty || 1);
  }

  const method = (data.payment_method || data.metode_bayar || 'tunai').toLowerCase();
  const amount = Number(data.total || data.amount || 0);
  if (method.includes('tunai') || method.includes('cash')) totalTunai += amount;
  else if (method.includes('debit') || method.includes('card')) totalDebit += amount;
  else if (method.includes('qris') || method.includes('gopay') || method.includes('ovo') || method.includes('dana') || method.includes('shopeepay')) totalQRIS += amount;
  totalTransaksi++;
}

const top5 = Object.entries(produkTerlaris)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, qty]) => `${name}: ${qty} pcs`)
  .join('\n');

const netSales = totalPenjualan - totalDiskon;

return [{
  json: {
    tanggal: new Date().toLocaleDateString('id-ID', {weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'}),
    total_transaksi: totalTransaksi,
    total_penjualan_kotor: totalPenjualan,
    total_diskon: totalDiskon,
    total_penjualan_bersih: netSales,
    total_ppn: totalPPN,
    tunai: totalTunai,
    debit_card: totalDebit,
    qris_ewallet: totalQRIS,
    produk_terlaris: top5,
    rata_rata_transaksi: totalTransaksi > 0 ? Math.round(netSales / totalTransaksi) : 0
  }
}];

